import torch
import torch.nn as nn

def run(query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, head_num: int, input_layout: str, pse=None, padding_mask=None, atten_mask=None, scale=1.0, keep_prob=1.0, pre_tockens=2147483647, next_tockens=2147483647, inner_precise=0, prefix=None, actual_seq_qlen=None, actual_seq_kvlen=None, sparse_mode=0, gen_mask_parallel=True, sync=False, softmax_layout='', sink=None):
    import torch_npu
    if head_num is None:
        head_num = 8
    if input_layout is None:
        input_layout = 'BSH'
    if scale is None:
        scale = 1.0
    if keep_prob is None:
        keep_prob = 1.0
    if pre_tockens is None:
        pre_tockens = 2147483647
    if next_tockens is None:
        next_tockens = 2147483647
    if inner_precise is None:
        inner_precise = 0
    if sparse_mode is None:
        sparse_mode = 0
    if gen_mask_parallel is None:
        gen_mask_parallel = True
    if sync is None:
        sync = False
    if softmax_layout is None:
        softmax_layout = ''
    outputs = torch_npu.npu_fusion_attention(query, key, value, head_num, input_layout, pse=pse, padding_mask=padding_mask, atten_mask=atten_mask, scale=scale, keep_prob=keep_prob, pre_tockens=pre_tockens, next_tockens=next_tockens, inner_precise=inner_precise, prefix=prefix, actual_seq_qlen=actual_seq_qlen, actual_seq_kvlen=actual_seq_kvlen, sparse_mode=sparse_mode, gen_mask_parallel=gen_mask_parallel, sync=sync, softmax_layout=softmax_layout, sink=sink)
    seed_t = torch.tensor(outputs[4], dtype=torch.int64, device=query.device)
    offset_t = torch.tensor(outputs[5], dtype=torch.int64, device=query.device)
    mask_len_t = torch.tensor(outputs[6], dtype=torch.int64, device=query.device)
    return (outputs[0], outputs[1], outputs[2], outputs[3], seed_t, offset_t, mask_len_t)

